example:
composition "Trance gate preview" { ample 1  tempo 128  master-seed 17 }

midi-clip phrase {
  chords Am F C G
  bars 4
}

synth pad {
  wave saw
  gain -12 dB
  from phrase.notes -> notes
}

tremolo trance {
  shape gate
  sync 1/16
  pattern "xdx.bxdx.xdx.x"
  depth 100
  from pad.audio -> audio
}

master master {
  from trance.audio -> audio
}
